export const CAPM_DOMAINS: Record<number, { name: string; w: number }> = {"1":{"name":"Project Management Fundamentals and Core Concepts","w":36},"2":{"name":"Predictive, Plan-Based Methodologies","w":17},"3":{"name":"Agile Frameworks/Methodologies","w":20},"4":{"name":"Business Analysis Frameworks","w":27}};

const CAPM_RAW_DATA: { title: string; desc: string; qs: CapmRawQuestion[] }[] = [{"title":"Project Fundamentals, Iron Triangle & Approaches","desc":"Project vs operations, portfolio dan PMO, triple constraint, tailoring, serta pemilihan life cycle (predictive, hybrid, agile).","qs":[{"src":"P5-Q131","d":1,"t":1,"q":"Why is a project undertaken?","o":["To increase the understanding of project management","To achieve better management of resources","To create a unique product, service, or result","To teach the discipline of program and portfolio management"],"a":[2],"w":["A project may help team members gain experience and improve their understanding of project management practices, but this is generally a secondary benefit rather than the primary purpose of the project. The reason projects are undertaken is to deliver a specific product, service, or result that addresses a business need or opportunity. Learning and professional development may occur during project execution, but they are not the defining purpose of a project. CAPM exam logic: PMI focuses on value delivery and achievement of business objectives rather than educational outcomes.","Effective resource management is important for project success, but it is not the fundamental reason a project is undertaken. Resources such as people, equipment, materials, and funding are inputs used to achieve project objectives. Organizations do not initiate projects solely to manage resources more effectively; they initiate projects to create value through a unique deliverable or outcome. CAPM exam logic: Distinguish between project objectives and the management practices used to achieve those objectives.","This is the correct answer because PMI defines a project as a temporary endeavor undertaken to create a unique product, service, or result. Projects are initiated when an organization needs to achieve a specific objective, solve a problem, respond to an opportunity, satisfy a regulatory requirement, or deliver business value through a unique outcome. Unlike operational work, which is ongoing and repetitive, projects have defined start and end points and produce something distinct. CAPM exam logic: The foundational PMI definition of a project centers on creating a unique product, service, or result.","Program management and portfolio management are organizational disciplines used to coordinate projects and align investments with strategic objectives. While projects could potentially be created to develop training materials or educational programs, teaching program and portfolio management is not the general reason projects are undertaken. The primary purpose of a project remains the creation of a unique product, service, or result that delivers value to stakeholders. CAPM exam logic: Questions based on project definitions often test the distinction between project outputs and organizational management disciplines."]},{"src":"P3-Q35","d":1,"t":1,"q":"An employee was hired to work on ongoing, repetitive activities in the accounting department. The employee's duties are managing and controlling day-to-day activities. Which type of managing is the employee performing?","o":["Project","Operations","Finance","Strategic"],"a":[1],"w":["Project is incorrect because a project is a temporary endeavor undertaken to create a unique product, service, or result. Projects have defined objectives, start and end dates, and are completed when their goals are achieved. The scenario describes recurring accounting activities that continue indefinitely as part of normal business operations. Since the work is ongoing rather than temporary and unique, it does not meet PMI’s definition of a project. CAPM exam logic: if work is repetitive, continuous, and supports day-to-day business functions, it is operational work rather than project work.","Operations is correct because operations management is responsible for managing and controlling ongoing, repetitive activities that sustain the organization and produce continuous business value. Unlike projects, which are temporary and create unique products, services, or results, operations involve routine work that is repeated over time. In this scenario, the employee is managing day-to-day accounting activities that support normal business functions, making this an example of operations management. PMI emphasizes the distinction between projects and operations because project work eventually transitions into operational activities once deliverables are implemented and maintained. CAPM exam logic: temporary and unique work indicates a project, while continuous and repetitive work indicates operations.","Finance is incorrect because finance refers to a functional business area rather than a type of management approach being described in the scenario. Financial management focuses on budgeting, investments, financial reporting, and resource allocation. Although the employee works in an accounting department, the key clue in the question is the management of ongoing, repetitive activities, which describes operational work rather than the finance function itself. CAPM exam logic: focus on the nature of the work being performed, not merely the department in which the work occurs.","Strategic is incorrect because strategic management focuses on defining long-term organizational goals, setting direction, allocating resources, and ensuring initiatives support business objectives. Strategic activities are typically performed by senior leadership and involve decisions that shape the future of the organization. The scenario describes managing routine accounting activities that occur regularly as part of normal business operations, not long-term organizational planning. CAPM exam logic: when a scenario emphasizes ongoing daily work, think operations rather than strategy."]},{"src":"PK-Q117","d":1,"t":1,"q":"Projects, programs, subsidiary portfolios, and operations managed as a group to achieve strategic objectives refers to?","o":["Portfolio management","Project management","Operations management","Program management"],"a":[0],"w":["Portfolio management is correct because it involves the centralized management of portfolios, subsidiary portfolios, programs, projects, and operations to achieve strategic organizational objectives. Portfolio management ensures that organizational investments are aligned with business strategy and value delivery goals. Portfolio managers evaluate, prioritize, authorize, and balance initiatives to optimize resource utilization, risk exposure, and expected benefits across the organization. The emphasis is on selecting and managing the right work rather than managing the execution of individual projects.\n\nCAPM exam logic: Keywords such as “strategic objectives,” “managed as a group,” “programs,” “projects,” and “operations” strongly indicate portfolio management. Portfolio management is PMI’s organizational-level framework for aligning investments with strategy.","Project management is incorrect because it involves applying knowledge, skills, tools, and techniques to achieve the objectives of a single project. Project management focuses on delivering specific outputs, outcomes, or deliverables within defined constraints. The scenario describes coordinating multiple organizational components, including projects, programs, portfolios, and operations, to support strategic objectives. That responsibility extends beyond the scope of managing an individual project.\n\nCAPM exam logic: When a question refers to organizational strategy and the management of multiple initiatives, the answer is typically portfolio management rather than project management.","Operations management is incorrect because operations focus on ongoing, repetitive activities that sustain the organization’s day-to-day business functions. Unlike projects, operations are continuous and do not have a defined end date. Although operations may be included within a portfolio, the question describes managing projects, programs, subsidiary portfolios, and operations collectively to achieve strategic objectives. That broader strategic coordination is the purpose of portfolio management, not operations management.\n\nCAPM exam logic: PMI distinguishes operations from portfolios by scope and purpose. Operations perform ongoing work, while portfolios align organizational investments with strategic goals.","Program management is incorrect because it involves coordinating related projects and program activities to realize benefits that would not be available if the projects were managed separately. Programs focus on benefit realization and coordinated outcomes. The definition in the question is broader than program management because it includes projects, programs, subsidiary portfolios, and operations managed together to support organizational strategy. Program management does not typically encompass this enterprise-level strategic oversight.\n\nCAPM exam logic: PMI distinguishes programs from portfolios by purpose. Programs focus on benefits from related projects, whereas portfolios focus on strategic alignment, prioritization, investment decisions, and organizational value."]},{"src":"P3-Q69","d":1,"t":3,"q":"An organization structure that standardizes the project-related governance processes and facilitates the sharing of resources, methodologies, tools, and techniques is referred to as:","o":["Project Management Office","Project Management Knowledge Area","Project Management System","Project Management Information System"],"a":[0],"w":["A Project Management Office (PMO) is an organizational structure that standardizes project-related governance processes and facilitates the sharing of resources, methodologies, tools, and techniques across projects. PMOs help establish consistency in project management practices, support governance, provide guidance to project managers, and promote alignment between projects and organizational objectives.\n\nThe scenario directly describes the core responsibilities of a PMO, including standardization, governance, and organizational support. Depending on the organization's needs, a PMO may provide support, exercise control, or directly manage projects. CAPM exam logic: When a question references standardized governance, shared methodologies, organizational oversight, and centralized project support, PMI typically points to a Project Management Office (PMO).","Incorrect. A Project Management Knowledge Area is a category of project management processes (e.g., Scope, Cost, Risk, Quality) . It is a conceptual grouping within the PMBOK framework, not an organizational structure responsible for governance or resource standardization.","Incorrect. A Project Management System refers to the collection of processes, tools, techniques, methodologies, and procedures used to manage a project . It describes a framework for managing projects, not an organizational entity that standardizes governance across projects.","Incorrect. A Project Management Information System (PMIS) is a set of tools and software applications used to support project management activities such as scheduling, cost control, and reporting . While it supports governance processes, it is not an organizational structure that standardizes governance or facilitates enterprise-wide methodology sharing."]},{"src":"P3-Q141","d":1,"t":2,"q":"Which three project constraints are most commonly associated with the traditional project management “triple constraint”?","o":["Schedule, sponsorship, scope","Sponsorship, risk, quality","Cost, scope, schedule","Resources, quality, communication"],"a":[2],"w":["Schedule and scope are part of the traditional triple constraint, but sponsorship is not. A sponsor provides direction, support, funding, and organizational alignment for the project but is not considered a project constraint. Because one of the three required triple-constraint elements is missing, this option is incorrect. CAPM exam logic: verify that all components of the traditional constraint model are present before selecting an answer.","Sponsorship, risk, and quality are incorrect because sponsorship is a governance role rather than a project constraint. While risk and quality are important factors that influence project success and may create trade-offs, they are not part of the traditional triple constraint model referenced in project management fundamentals. CAPM exam logic: distinguish between project constraints and project roles or governance functions.","Cost, scope, and schedule are correct because they form the traditional project management “triple constraint.” These constraints are closely related: changes to one often affect one or both of the others. For example, expanding scope may require additional time or budget, while shortening the schedule may increase costs. Project managers must continuously balance these competing factors to achieve project objectives while meeting stakeholder expectations. CAPM exam logic: when a question specifically references the traditional triple constraint, think scope, schedule, and cost.","Resources and quality can influence project outcomes and often require trade-off decisions, but communication is a project management knowledge area or management activity rather than a project constraint. This option does not represent the traditional triple constraint model of scope, schedule, and cost. CAPM exam logic: be careful not to confuse management processes with project constraints."]},{"src":"P3-Q131","d":2,"t":1,"q":"A project is composed of three phases. Detailed scope, schedule, and cost baselines for each phase have been approved by the major stakeholders before execution begins, and there is minimal ability to change those baselines during project execution. Which development approach is being used?","o":["Incremental approach","Hybrid approach","Iterative approach","Predictive approach"],"a":[3],"w":["Incremental approaches deliver usable portions of a product or solution over time, with each increment adding functionality or capability. The focus is on delivering value in stages rather than waiting until the entire solution is complete.\n\nThe scenario does not describe progressive delivery of functionality through multiple increments. Instead, it emphasizes approved baselines and limited change flexibility, which are characteristics of predictive planning. CAPM exam logic: Candidates should distinguish between incremental delivery of product functionality and predictive projects that primarily emphasize detailed upfront planning and baseline control.","Hybrid approaches combine elements of predictive and adaptive delivery methods. They are commonly used when some portions of the project benefit from detailed upfront planning while other portions require flexibility, experimentation, or iterative development.\n\nThe scenario provides no indication that adaptive practices, iterative delivery, or evolving requirements are being used. Instead, the project is characterized by approved baselines and limited ability to change them during execution. CAPM exam logic: When a scenario describes predominantly plan-driven behavior with stable baselines and controlled change, PMI generally points to a predictive rather than hybrid approach.","Iterative approaches use repeated cycles to progressively refine a solution as more information becomes available. Each iteration builds on feedback, learning, and evolving understanding of stakeholder needs. Requirements may be elaborated and refined throughout the project rather than being fully defined at the beginning.\n\nThe scenario describes approved baselines and limited ability to change them during execution, which is inconsistent with the flexibility and progressive elaboration associated with iterative delivery. CAPM exam logic: When PMI emphasizes stable baselines and tightly controlled changes, candidates should think predictive rather than iterative approaches.","Predictive approaches establish scope, schedule, and cost baselines early in the project life cycle and rely on detailed upfront planning before execution begins. Project work is performed according to approved plans, and changes are generally managed through formal change control processes.\n\nThe scenario emphasizes approved baselines and minimal ability to modify them during execution, which are defining characteristics of predictive delivery. CAPM exam logic: PMI typically associates stable requirements, detailed upfront planning, and tightly controlled changes with predictive project management."]},{"src":"PK-Q111","d":2,"t":1,"q":"A new project was approved and the project manager is discussing the most suitable delivery approach with the project sponsor. Which three of the following are characteristics of a traditional project delivered using a linear delivery approach? (Choose three.)","o":["Routine and repetitive activities","Few expected simple scope change requests","Use of established templates","Many expected simple scope change requests","Collocated project teams"],"a":[0,1,2],"w":["Routine and repetitive activities is correct because predictive projects rely on well-defined processes, detailed planning, and repeatable execution practices. Work is typically organized through established procedures and follows a structured sequence of activities throughout the project lifecycle. Predictive approaches are most effective when requirements are relatively stable and the work can be planned in advance with a reasonable degree of certainty. Repetitive processes support consistency, governance, quality management, and schedule control.\n\nCAPM exam logic: PMI often associates predictive delivery with process stability, repeatability, formal planning, and controlled execution. When an answer emphasizes predictable and repeatable work patterns, it is often a strong indicator of a traditional linear approach.","Few expected simple scope change requests is correct because predictive projects emphasize detailed upfront scope definition, requirements documentation, and comprehensive planning before execution begins. As a result, the project team expects relatively few changes once work is underway. When changes are necessary, they are evaluated through formal integrated change control processes to assess their impact on scope, schedule, cost, quality, and project objectives. The goal is to maintain stability and predictability throughout project execution.\n\nCAPM exam logic: One of the strongest indicators of a traditional linear approach is stable requirements combined with controlled change management. When an answer highlights limited expected changes and formal control processes, it typically aligns with predictive project delivery.","Use of established templates is correct because traditional linear (predictive) projects rely heavily on standardized processes, documented procedures, and predefined project artifacts. Templates help ensure consistency in planning, execution, monitoring, reporting, and governance across the project lifecycle. Predictive environments emphasize detailed upfront planning and formal control mechanisms. Standard templates support repeatability, improve communication, reduce ambiguity, and help ensure compliance with organizational standards and quality requirements.\n\nCAPM exam logic: PMI commonly associates predictive approaches with formal documentation, structured planning, and established governance practices. When an answer references standardized templates, procedures, or documented processes, it is often a strong indicator of a traditional linear delivery approach.","Many expected simple scope change requests is incorrect because predictive projects are designed around a well-defined scope that is established early in the project lifecycle. Significant effort is invested in requirements gathering and planning to reduce uncertainty and limit the need for frequent changes during execution. Although scope changes can occur in predictive projects, they are typically managed through formal change control processes and are not expected to happen frequently. Environments where requirements evolve continuously and changes are anticipated throughout delivery are more characteristic of adaptive or Agile approaches.\n\nCAPM exam logic: PMI frequently contrasts predictive and adaptive delivery by how they handle change. Predictive projects seek scope stability and controlled changes, whereas adaptive projects expect and embrace ongoing requirement evolution.","Collocated project teams is incorrect because team colocation is not a defining characteristic of a traditional linear (predictive) delivery approach. Predictive projects can be executed by collocated, distributed, or hybrid teams depending on organizational needs and project constraints. The defining characteristics of predictive delivery are detailed upfront planning, stable requirements, formal governance, and controlled change management. Team location may influence communication effectiveness but does not determine the delivery approach.\n\nCAPM exam logic: PMI often includes practices that can be used in multiple delivery approaches as distractors. Focus on characteristics that specifically distinguish predictive delivery from adaptive delivery."]},{"src":"P3-Q49","d":3,"t":1,"q":"A company must implement sales software because it is opening a new branch in a foreign market. Although this software is used in every domestic branch, multiple changes are expected during the implementation because it is a foreign location. Which type of life cycle would the project manager use in this case?","o":["Product life cycle","Waterfall life cycle","Hybrid life cycle","Predictive life cycle"],"a":[2],"w":["A product life cycle describes the stages a product passes through from introduction to retirement. It focuses on the evolution of the product in the marketplace rather than the approach used to manage project work.\n\nThe question asks which life cycle or development approach should be used to deliver the project. CAPM exam logic: PMI distinguishes between the product life cycle, which describes the product's existence, and project life cycles, which describe how project work is organized and performed.","A waterfall life cycle is a specific type of predictive life cycle in which project phases are performed sequentially, with each phase generally completed before the next begins. Waterfall approaches work best when requirements are well understood, stable, and unlikely to change throughout the project.\n\nThe scenario states that multiple changes are expected because the software is being implemented in a foreign market. This anticipated need for adaptation reduces the suitability of a strictly sequential waterfall approach. CAPM exam logic: When PMI describes known solution components but expects significant adjustments during implementation, candidates should recognize that a more flexible approach, such as hybrid, is typically more appropriate than a traditional waterfall life cycle.","A hybrid life cycle combines predictive and adaptive elements within the same project. It is particularly useful when some aspects of the work are well understood and can be planned in advance, while other aspects involve uncertainty, evolving requirements, or a need for flexibility.\n\nIn this scenario, the software solution already exists and has been implemented successfully in domestic branches, which supports the use of predictive practices. However, the foreign-market implementation is expected to require multiple changes and adaptations, creating a need for adaptive practices. CAPM exam logic: When a project contains both stable and uncertain elements, PMI generally favors a hybrid approach because it balances planning, governance, and flexibility.","A predictive life cycle is most appropriate when scope, requirements, and solution details are largely known and stable before execution begins. Planning is performed upfront, and changes are expected to be relatively limited and managed through formal change control processes.\n\nAlthough the organization is implementing an existing software solution that has already been deployed successfully in other branches, the scenario indicates that multiple changes are expected because of the foreign-market environment. CAPM exam logic: When PMI describes a project with both known elements and anticipated adaptation, a purely predictive approach is typically less suitable than a hybrid approach."]},{"src":"PK-Q25","d":3,"t":1,"q":"An organization has a team of specialists dedicated to solving a complex problem. What project management approach should they consider?","o":["Hybrid","Iterative","Agile","Predictive"],"a":[2],"w":["Hybrid approaches combine elements of predictive and adaptive delivery methods. They are often used when some portions of the work are well understood and benefit from detailed upfront planning, while other portions require flexibility and adaptation. The scenario does not indicate a need to combine predictive and adaptive practices. Instead, it focuses on a team working to solve a complex problem, which more directly aligns with adaptive Agile principles.\n\nCAPM exam logic: PMI generally reserves Hybrid for situations where both predictive and adaptive characteristics are present rather than purely complex problem-solving environments.","Iterative approaches use repeated cycles to progressively refine a solution as more information becomes available. They are commonly used when requirements are not fully understood at the beginning of the project and learning occurs throughout development. Therefore, iterative delivery can be appropriate for complex problem-solving environments. However, Agile is generally considered a broader adaptive approach that combines iterative development with continuous stakeholder feedback, collaboration, prioritization, and incremental value delivery.\n\nCAPM exam logic: When both Agile and Iterative appear as answer choices, PMI often treats Agile as the more comprehensive adaptive approach, while Iterative refers specifically to the repeated refinement cycle.","Agile approaches are particularly effective when solving complex problems that involve uncertainty, learning, experimentation, and evolving solutions. Agile emphasizes collaboration, iterative development, continuous feedback, and frequent adaptation, allowing teams to refine their approach as new information becomes available. PMI recognizes complexity and uncertainty as key factors that often favor adaptive delivery approaches.\n\nCAPM exam logic: When a scenario involves complex problem-solving where the solution is not fully known upfront and learning occurs throughout the work, Agile is typically the preferred approach because it supports rapid feedback and adaptation.","Predictive approaches are most effective when project scope, requirements, and solution characteristics can be defined early and are expected to remain relatively stable throughout the project. Planning is performed largely upfront, with work executed according to established baselines and changes managed through formal change control processes. Complex problems often involve uncertainty, experimentation, discovery, and evolving understanding of the solution, making it difficult to fully define the work at the outset.\n\nCAPM exam logic: PMI generally associates predictive approaches with low-uncertainty environments and well-understood outcomes, whereas complex problem-solving situations more often favor adaptive approaches that support learning and adjustment throughout the project life cycle."]},{"src":"P3-Q32","d":1,"t":1,"q":"Why is tailoring in a project necessary?","o":["Each project is unique","An artifact must be produced","Requirements keep changing","A tool or technique is required"],"a":[0],"w":["Each project is unique is correct because projects differ in factors such as complexity, size, risk, stakeholder involvement, organizational culture, regulatory requirements, and delivery approach. PMI recognizes that no single process framework is appropriate for every project, so teams tailor processes, governance, methods, and documentation to best support the project’s objectives and value delivery. CAPM exam logic: tailoring exists because every project has unique characteristics that require adapting the project management approach to fit the specific situation.","An artifact must be produced is incorrect because the need to create a document, report, or other artifact does not determine whether tailoring is necessary. Tailoring focuses on determining the appropriate level of rigor, documentation, governance, and process application for a specific project. CAPM exam logic: PMI emphasizes tailoring to fit project needs rather than producing documentation for its own sake.","Requirements keep changing is incorrect because tailoring is not performed solely in response to changing requirements. Tailoring applies to all projects and involves selecting the most appropriate processes, methods, tools, governance approaches, and deliverables based on the project’s characteristics. CAPM exam logic: tailoring is broader than change management and applies regardless of whether the project uses predictive, agile, or hybrid approaches.","A tool or technique is required is incorrect because tools and techniques are selected as part of tailoring decisions, not the reason tailoring is performed. Project teams first assess project characteristics and then determine which tools, methods, and practices are most appropriate. CAPM exam logic: tailoring drives the selection of tools and techniques, not the other way around."]}]},{"title":"The 10 Knowledge Areas, Project Roles & Stakeholders","desc":"Process group, EEF vs OPA, struktur organisasi, peran PM, emotional intelligence, konflik, RACI dan stakeholder.","qs":[{"src":"PK-Q140","d":1,"t":1,"q":"What is the purpose of the project management process groups?","o":["To define a new project","To track and monitor processes easily","To link specific process inputs and outputs","To logically group processes to achieve specific project objectives"],"a":[3],"w":["Defining a new project is incorrect because that activity is primarily associated with the Initiating Process Group, particularly activities such as developing the project charter and identifying stakeholders. However, the question asks about the overall purpose of Process Groups, not the purpose of a single Process Group. Collectively, the Process Groups provide a framework for managing project work from authorization through closure. Their purpose extends beyond defining a project and includes planning, executing, monitoring and controlling, and formally closing project work.\n\nCAPM exam logic: The Initiating Process Group helps authorize and define a project, while all Process Groups together provide the overall project management framework.","Tracking and monitoring processes is incorrect because monitoring and controlling is only one of the five Process Groups. While Process Groups support performance measurement and control, their overall purpose is broader than monitoring project work. Together, the Process Groups provide a complete framework for managing projects, including authorization, planning, execution, monitoring and controlling, and closure. Focusing only on monitoring overlooks the broader role Process Groups play in achieving project objectives.\n\nCAPM exam logic: Monitoring and Controlling is one Process Group, whereas the Process Groups collectively support the full management of a project.","Linking specific process inputs and outputs is incorrect because inputs and outputs are characteristics of individual project management processes rather than the primary purpose of Process Groups. Processes interact through inputs, tools and techniques, and outputs, but this does not explain why Process Groups exist. Process Groups are used to organize related project management activities according to their purpose and contribution to project objectives. They provide structure and governance rather than simply describing information flow between processes.\n\nCAPM exam logic: Inputs and outputs describe process interactions, whereas Process Groups organize project management activities into a logical management framework.","To logically group processes to achieve specific project objectives is correct because Process Groups organize project management activities according to their purpose. PMI uses Process Groups to provide a structured framework for initiating, planning, executing, monitoring and controlling, and closing project work. Process Groups help ensure that project management activities are performed in a coordinated and integrated manner throughout the project. They support the achievement of project objectives by providing a logical structure for managing work, making decisions, controlling performance, and delivering outcomes.\n\nCAPM exam logic: Process Groups organize project management processes by function and purpose. They provide a framework for managing projects effectively and are not the same as project phases or the project life cycle."]},{"src":"P3-Q118","d":1,"t":1,"q":"Company A has just been notified about a new legal requirement for its business operations. What is the classification of this item?","o":["Internal enterprise environmental factor","External enterprise environmental factor","Organizational process asset","Risk register database"],"a":[1],"w":["Internal Enterprise Environmental Factors (EEFs) are conditions that exist within the organization and can influence project performance. Examples include organizational culture, structure, governance frameworks, internal systems, available resources, and employee capabilities.\n\nA new legal requirement does not originate from within the organization. Because it is imposed by an external authority, it cannot be classified as an internal EEF. CAPM exam logic: when determining whether an EEF is internal or external, focus on where the influence originates rather than where its effects are felt.","Laws, regulations, government policies, industry standards, and legal requirements are examples of external Enterprise Environmental Factors (EEFs). These factors originate outside the organization but can significantly influence project planning, execution, compliance activities, costs, schedules, and risk management.\n\nProject teams must consider external EEFs because they often create constraints, obligations, or opportunities that affect project decisions. A newly imposed legal requirement clearly falls into this category because it originates from an external regulatory or legal source. CAPM exam logic: regulatory and legal requirements are classic examples of external EEFs and are frequently tested on the CAPM exam.","Organizational Process Assets (OPAs) are internal organizational resources that support project work. Examples include policies, procedures, templates, historical information, lessons learned repositories, and knowledge management systems.\n\nA newly imposed legal requirement is not created or maintained by the organization and therefore is not an OPA. The organization may update its policies and procedures to comply with the requirement, and those updated policies could become OPAs, but the legal requirement itself remains an external EEF. CAPM exam logic: OPAs originate within the organization, whereas laws and regulations originate outside the organization.","A risk register is a project document used to record identified risks, their causes, probability, impact, response strategies, owners, and status. It serves as a repository for managing project risks throughout the project life cycle.\n\nAlthough a new legal requirement may introduce risks that are documented in the risk register, the requirement itself is not a risk register or a risk management artifact. CAPM exam logic: distinguish between an event or condition that affects the project and the documents used to manage its impacts."]},{"src":"P3-Q91","d":1,"t":1,"q":"Which of the following best represents Organizational Process Assets (OPAs) that can affect a project?","o":["Marketplace conditions and legal restrictions","Resource availability and employee capability","Policies and lessons learned from other projects","Information technology software and employee capability"],"a":[2],"w":["Marketplace conditions and legal restrictions (D) is incorrect because these are external Enterprise Environmental Factors. External EEFs include market conditions, regulatory requirements, legal constraints, industry standards, and economic influences that can affect project decisions and outcomes. While these factors must be considered during planning and execution, they are not organizational assets created, maintained, or controlled by the organization. CAPM exam logic: external influences such as laws, regulations, and market conditions are EEFs, whereas OPAs consist of internal organizational knowledge and process assets.","Resource availability and employee capability (C) is incorrect because both items are Enterprise Environmental Factors rather than Organizational Process Assets. Resource availability reflects organizational conditions that affect staffing decisions, while employee capability refers to the skills and competencies of available personnel. These factors influence project planning and execution but are not documented assets such as policies, procedures, templates, or lessons learned repositories. CAPM exam logic: if an answer describes organizational conditions or capabilities rather than documented organizational knowledge, it is typically an EEF rather than an OPA.","Policies and lessons learned from other projects (A) is correct because Organizational Process Assets (OPAs) are internal organizational resources that can be used to support project planning and execution. OPAs include policies, procedures, templates, guidelines, historical information, lessons learned repositories, and organizational knowledge bases that have been developed and maintained by the organization over time. These assets help improve consistency, efficiency, and decision-making across projects. CAPM exam logic: when identifying OPAs, look for documented organizational knowledge, processes, policies, procedures, and historical information that can be reused by the project team.","Information technology software and employee capability (B) is incorrect because these are examples of Enterprise Environmental Factors (EEFs), not Organizational Process Assets. EEFs are conditions that exist within or outside the organization and influence how projects are managed. Technology infrastructure, software tools, organizational culture, and employee skills affect project performance, but they are environmental conditions rather than documented organizational assets. CAPM exam logic: OPAs are reusable organizational knowledge and governance resources, while EEFs are conditions that influence the project environment."]},{"src":"P3-Q65","d":1,"t":3,"q":"In what type of organizational structure does a project manager develop their role and work with a team assigned by job function?","o":["Virtual","Functional","Matrix - strong","Matrix - balanced"],"a":[1],"w":["This option is incorrect because a virtual organization is defined primarily by how team members collaborate rather than by authority distribution. Virtual teams are often geographically dispersed and rely on technology to communicate and coordinate work.\n\nA virtual organization may operate within functional, matrix, projectized, or hybrid structures. CAPM exam logic: distinguish organizational structure (functional, matrix, projectized) from team-location concepts such as virtual teams.","This is correct because in a functional organization, team members are grouped according to their areas of specialization, such as engineering, finance, marketing, or operations. Functional managers retain authority over resources, budgets, and work assignments, while project work is typically performed within functional departments.\n\nThe project manager, if one exists, usually has limited authority and may function as a coordinator or expediter rather than having direct control over project resources. Team members remain aligned with their functional departments and report primarily through functional management channels. CAPM exam logic: when resources are organized by job function and functional managers hold most of the authority, the organizational structure is functional.","This option is incorrect because a strong matrix organization provides the project manager with substantial authority and greater control over project resources. Team members often have a stronger reporting relationship to the project manager than in other matrix structures, and project work is a primary organizational focus.\n\nThis differs significantly from a functional organization, where authority remains with functional managers and resources are assigned according to departmental specialization. CAPM exam logic: strong matrix structures resemble projectized organizations more than functional organizations in terms of project manager authority.ct resources. Team members are not primarily controlled by job function managers, and the project manager’s role is well established rather than developing within functional constraints.","This option is incorrect because a balanced matrix organization shares authority between the project manager and functional managers. Both roles contribute to resource allocation, decision-making, and project execution.\n\nAlthough team members may still belong to functional departments, the project manager has a formally recognized role and meaningful authority. CAPM exam logic: balanced matrix means shared power, whereas functional organizations place most authority with functional managers."]},{"src":"P3-Q110","d":1,"t":3,"q":"Which role does the project manager resemble best?","o":["Functional manager","Facilities supervisor","Orchestra conductor","School principal"],"a":[2],"w":["This option is incorrect because a functional manager typically leads a specific department such as engineering, finance, marketing, or operations. Their primary responsibility is managing ongoing departmental activities, developing staff capabilities, and ensuring efficient functional performance.\n\nA project manager, in contrast, works across organizational boundaries and coordinates contributions from multiple functional areas. While a functional manager often focuses on resource management within a single discipline, the project manager focuses on integrating work across disciplines to achieve project objectives. CAPM exam logic: understand the distinction between functional authority and project integration responsibilities when comparing organizational roles.","This option is incorrect because a facilities supervisor is primarily responsible for maintaining operational environments, physical infrastructure, equipment, and ongoing services. The focus is on sustaining existing operations rather than delivering a unique project outcome.\n\nProjects are temporary endeavors undertaken to create a unique product, service, or result, whereas facilities management is generally an operational function. While both roles require coordination and oversight, the facilities supervisor analogy does not capture the project manager's responsibility for integrating cross-functional work to achieve temporary project objectives. CAPM exam logic: distinguish between project work, which is temporary and unique, and operational work, which is ongoing and repetitive.","This option is correct because PMI frequently describes the project manager as an integrator who coordinates people, resources, processes, and activities to achieve a common objective. An orchestra conductor does not personally play every instrument but ensures that all musicians work together in a synchronized and effective manner to produce the desired outcome.\n\nSimilarly, project managers coordinate specialists from different disciplines, facilitate communication, resolve conflicts, manage dependencies, and align work with project objectives. Their success depends on integration, leadership, and collaboration rather than technical execution of every task. CAPM exam logic: when PMI uses analogies for the project manager's role, the orchestra conductor is often the best representation because it emphasizes coordination and integration across diverse contributors.","This option is incorrect because a school principal provides leadership, governance, policy implementation, and operational oversight within a permanent organizational structure. Although leadership, communication, and stakeholder management are important aspects of both roles, the analogy is incomplete.\n\nThe project manager's primary responsibility is integrating diverse project activities and coordinating specialized contributors toward a temporary objective with defined constraints. A principal oversees an ongoing institution rather than a temporary endeavor. CAPM exam logic: select the analogy that best represents integration, coordination, and orchestration of project work rather than general leadership alone."]},{"src":"P5-Q33","d":1,"t":3,"q":"What does emotional intelligence help provide to project managers and teams?","o":["Less project team turnover and more stress","Self-recognition and ability to manage the emotions of others","More tension and more project control","Greater self-awareness and project team turnover"],"a":[1],"w":["Less project team turnover and more stress is incorrect because emotional intelligence is intended to improve interpersonal relationships, communication, trust, and team well-being. Emotionally intelligent leaders recognize emotions in themselves and others, respond appropriately to concerns, and create supportive working environments. While stronger leadership can contribute to lower turnover, increased stress is the opposite of the typical outcome associated with emotional intelligence. CAPM exam logic: PMI associates emotional intelligence with healthier team dynamics, stronger collaboration, and reduced conflict, not increased stress.","Self-recognition and the ability to manage the emotions of others is correct because emotional intelligence includes self-awareness, self-management, social awareness, and relationship management. Project managers with strong emotional intelligence understand their own emotions, recognize the emotions and concerns of stakeholders and team members, and adapt their behavior to communicate effectively, resolve conflicts, motivate others, and build productive relationships. These skills are especially important in diverse project environments where collaboration, stakeholder engagement, and team performance directly influence project success. CAPM exam logic: PMI views emotional intelligence as a key leadership competency that helps project managers improve communication, stakeholder relationships, conflict resolution, and team effectiveness.","More tension and more project control is incorrect because emotional intelligence is intended to reduce tension rather than increase it. By improving empathy, active listening, emotional awareness, and conflict management, emotionally intelligent leaders foster cooperation and trust within teams. Although better relationships and communication can indirectly improve project performance and control, those benefits come from reducing interpersonal friction, not creating additional tension. CAPM exam logic: Emotional intelligence strengthens leadership effectiveness by promoting collaboration and positive team dynamics, not by increasing workplace tension.","Greater self-awareness and project team turnover is incorrect because self-awareness is one of the core components of emotional intelligence, but increased team turnover is not. Emotionally intelligent project managers build trust, psychological safety, and stronger working relationships, which can improve team engagement and retention. Because this option combines a correct characteristic with an incorrect outcome, it is not the best answer. CAPM exam logic: Watch for answer choices that mix one correct concept with one incorrect concept; such options are typically distractors on the CAPM exam."]},{"src":"P5-Q6","d":1,"t":5,"q":"A project manager can choose from several techniques to resolve conflicts between team members. Which technique can result in a win-win situation?","o":["Smooth/ Accommodate","Withdraw/Avoid","Collaborate/Problem Solve","Compromise/Reconcile"],"a":[2],"w":["Smooth/Accommodate emphasizes areas of agreement and downplays differences to maintain harmony within the team. While this approach can reduce tension in the short term, it does not address the underlying cause of the conflict. In many cases, one party accommodates the other’s position, resulting in an outcome that favors relationship preservation over problem resolution. CAPM exam logic: PMI recognizes smoothing as a temporary conflict management technique, but it does not create a true win-win resolution because the root issue remains unresolved.","Withdraw/Avoid involves postponing or avoiding the conflict altogether rather than addressing it directly. This technique may be appropriate when emotions are high, when additional information is needed, or when the issue is relatively minor. However, because the conflict remains unresolved, this approach does not produce a mutually beneficial outcome and may allow the problem to persist. CAPM exam logic: PMI expects project managers to address important conflicts proactively; avoiding conflict may be useful temporarily but does not result in a win-win solution.","Collaborate/Problem Solve is the conflict resolution technique that seeks to fully understand the underlying issue and identify a solution that satisfies all parties. By encouraging open discussion, examining different perspectives, and addressing the root cause of the conflict, the team can reach a mutually beneficial outcome. Although this approach often requires more time and effort than other techniques, it typically produces the most durable solution and strengthens team relationships. CAPM exam logic: PMI identifies Collaborate/Problem Solve as the preferred conflict resolution approach because it focuses on resolving the root cause and achieving a true win-win outcome.","Compromise/Reconcile seeks a middle ground where each party gives up something to reach an acceptable solution. While this technique can resolve conflicts more quickly than collaboration, neither side receives everything it wants. As a result, the outcome is generally considered a partial win for both parties rather than a true win-win solution. CAPM exam logic: PMI views compromise as a practical conflict resolution technique, but it does not fully satisfy all parties and therefore is not considered the primary win-win approach."]},{"src":"P3-Q25","d":1,"t":3,"q":"Responsible, accountable, consult and inform (RACI) is an example of which of the following?","o":["Responsibility assignment matrix (RAM)","Resource management plan","Organization chart","Text-oriented format"],"a":[0],"w":["A Responsibility Assignment Matrix (RAM) is a tool used to illustrate the relationship between project work and the team members or stakeholders responsible for that work. It helps clarify roles, responsibilities, accountability, and communication expectations, reducing confusion and improving coordination.\n\nA RACI chart is one of the most common forms of a RAM. The letters identify who is Responsible for performing the work, Accountable for the outcome, Consulted for input, and Informed about progress or decisions. CAPM exam logic: remember that RACI is not a separate project management artifact category; it is a specific type of Responsibility Assignment Matrix used to define and communicate roles.","The Resource Management Plan describes how project resources will be acquired, developed, managed, and released throughout the project life cycle. It provides guidance for managing team and physical resources but is not itself a responsibility assignment tool.\n\nA RACI chart may be referenced within or supported by the Resource Management Plan, but it remains a separate artifact used to define accountability and responsibility for specific work. CAPM exam logic: distinguish between management plans that provide guidance and tools that assign responsibilities.","An organizational chart illustrates reporting relationships, authority structures, and the hierarchy within a project or organization. It helps stakeholders understand who reports to whom and how the organization is structured.\n\nA RACI chart serves a different purpose by assigning responsibility and accountability for specific activities or deliverables. CAPM exam logic: organization charts show reporting relationships, whereas RAMs and RACI charts show responsibility relationships for project work.","A text-oriented format documents roles, responsibilities, and authority levels in narrative form rather than in a structured table or matrix. Examples include written role descriptions and responsibility statements contained within project documentation.\n\nA RACI chart is presented as a matrix that maps activities or deliverables to stakeholders and team members. CAPM exam logic: distinguish between narrative role descriptions (text-oriented formats) and structured responsibility mapping tools such as RAMs."]},{"src":"PK-Q1","d":4,"t":2,"q":"At what stages of a project should the Identify Stakeholders process be performed?","o":["Only when the project manager is concerned about stakeholder satisfaction","At the beginning of the project only","When the project charter is produced, at the beginning of each phase, and when significant changes occur","When beginning each phase of the project"],"a":[2],"w":["Stakeholder identification is not performed only when concerns about stakeholder satisfaction arise. It is a formal project management activity used to identify individuals, groups, or organizations that may affect or be affected by the project and to understand their interests, influence, and expectations. PMI promotes proactive stakeholder engagement rather than waiting for issues or dissatisfaction to occur.\n\nCAPM exam logic: Stakeholder management begins with early identification and continuous reassessment, not as a reactive response to stakeholder concerns.","Identify Stakeholders is first performed at the beginning of the project, typically in conjunction with the development of the project charter. However, PMI emphasizes that stakeholder identification is an ongoing activity and should be revisited throughout the project life cycle as new stakeholders emerge or existing stakeholders change influence or interest. Therefore, performing it only once is insufficient.","Identify Stakeholders is initially performed during project initiation, often while developing the project charter, and should be revisited at the beginning of phases and whenever significant changes occur that may affect stakeholder influence, interest, expectations, or project outcomes. New stakeholders may emerge, organizational structures may change, and existing stakeholders may gain or lose influence as the project progresses. Ongoing stakeholder identification helps ensure that communication, engagement, expectations, and project decisions remain aligned with current stakeholder needs.\n\nCAPM exam logic: PMI treats stakeholder identification as an iterative activity that begins early but continues throughout the project life cycle whenever changes could affect stakeholder relationships or project success.","Performing Identify Stakeholders only at the beginning of each phase is incomplete. While stakeholder identification should be revisited at phase boundaries, PMI states that it should also occur at project initiation and whenever significant changes happen. Limiting it to phase beginnings does not reflect the continuous and iterative nature of stakeholder management."]},{"src":"P3-Q59","d":4,"t":2,"q":"What tool can be used to track how involved and interested stakeholders are in a project?","o":["Stakeholder communications plan","Stakeholder engagement assessment matrix","Stakeholder register","Stakeholder meetings"],"a":[1],"w":["Stakeholder communications plan is incorrect because it defines how information will be communicated to stakeholders, including communication methods, frequency, and responsibilities. While the plan may be informed by stakeholder engagement assessments, it does not itself measure or track stakeholder interest, influence, or engagement levels. CAPM exam logic: communication plans define how communication occurs, while stakeholder assessment tools help evaluate stakeholder engagement.","Stakeholder Engagement Assessment Matrix is correct because it helps the project manager evaluate and compare stakeholders’ current and desired levels of engagement with the project. By identifying gaps between current and desired engagement levels, the project team can develop appropriate communication and engagement strategies to increase stakeholder support and involvement. This tool helps monitor stakeholder engagement throughout the project lifecycle and supports effective stakeholder management. CAPM exam logic: when a question asks how stakeholder engagement levels are assessed or monitored, the Stakeholder Engagement Assessment Matrix is typically the best answer.","Stakeholder register is incorrect because it documents stakeholder information such as identities, roles, interests, expectations, influence, and communication requirements. Although it contains valuable stakeholder information, it is not specifically designed to compare current and desired engagement levels or track engagement changes over time. CAPM exam logic: the stakeholder register identifies and documents stakeholders, while engagement assessment tools evaluate stakeholder engagement levels.","Stakeholder meetings is incorrect because meetings are an engagement technique used to communicate, gather feedback, resolve concerns, and build relationships with stakeholders. However, meetings do not provide a structured method for assessing or tracking stakeholder engagement levels across the project. CAPM exam logic: meetings are stakeholder engagement activities, whereas assessment matrices are tools used to evaluate stakeholder engagement and involvement."]}]},{"title":"From Business Problem to Project Charter","desc":"Alasan memulai project, business case, cost-benefit, project charter beserta tools & techniques Develop Project Charter.","qs":[{"src":"P3-Q43","d":1,"t":1,"q":"Company A's accountant sends notification about a change in the company's tax classification. Why would a project have to be initiated?","o":["To meet regulatory and legal requirements","To change business and technological strategies","To satisfy stakeholder requests","To improve processes and services"],"a":[0],"w":["This option is correct because regulatory, legal, and compliance requirements are recognized PMI project initiation drivers. When external authorities introduce new rules, classifications, reporting obligations, or legal requirements, organizations often must initiate projects to ensure compliance.\n\nA change in tax classification may require modifications to accounting systems, financial reporting processes, business procedures, documentation, controls, training, or software configurations. These changes are temporary efforts undertaken to create a compliant future state, which fits the definition of a project. CAPM exam logic: when a scenario involves laws, regulations, compliance obligations, audits, or governmental requirements, regulatory and legal requirements are usually the strongest project initiation trigger.","This option is incorrect because changes in business strategy or technology strategy can certainly trigger projects, but the scenario does not describe a strategic initiative. Instead, it describes a change in the organization's tax classification, which is a compliance-related event requiring the organization to adapt to external requirements.\n\nPMI recognizes that projects may be initiated because of strategic opportunities, market demands, technological advances, or regulatory changes. Since the trigger in this scenario originates from a tax-related requirement, a strategy-driven explanation is less appropriate than a compliance-driven one. CAPM exam logic: identify the specific project initiation trigger described in the scenario rather than selecting a broadly plausible reason for starting a project.","This option is incorrect because stakeholder requests can be legitimate reasons to initiate projects when stakeholders seek new products, services, capabilities, or organizational changes. However, the scenario does not describe a discretionary stakeholder request.\n\nThe accountant is communicating a change in tax classification that the organization must address. The driver is external compliance rather than a stakeholder preference or business request. CAPM exam logic: when both a stakeholder-related answer and a regulatory-related answer appear, choose the regulatory answer if the scenario involves mandatory legal or compliance obligations.","This option is incorrect because process improvement projects are typically initiated to increase efficiency, reduce costs, improve quality, or enhance customer value. While organizations frequently launch projects for operational improvement, the scenario does not indicate any desire to improve existing business processes.\n\nThe key clue is the notification regarding a change in tax classification. Such changes often require updates to systems, reporting methods, policies, procedures, or documentation to maintain compliance with external regulations. CAPM exam logic: distinguish between internally driven improvement initiatives and externally driven compliance requirements."]},{"src":"PK-Q103","d":4,"t":1,"q":"A business manager wants to start a project to launch a new product. How should the manager initiate the project?","o":["Assign a project manager to the project and ask them to document the project scope.","Develop a business case to justify the project and support authorization.","Ask a small team to produce a prototype of the product before full-scale development.","Discuss the project requirements with the team for alternative products in the market."],"a":[1],"w":["Assigning a project manager and documenting the project scope is incorrect because these activities typically occur after the project has been justified and approved. While assigning a project manager may occur during initiation, detailed scope definition is generally performed during planning after the project has been formally authorized. The organization must first determine whether the project should proceed before investing effort in detailed planning activities. Without a business case and authorization, there is no confirmed basis for defining scope in detail.\n\nCAPM exam logic: PMI prioritizes business justification and project authorization before detailed planning activities such as scope definition.","Developing a business case is correct because the business case provides the justification for investing organizational resources in a proposed project. It evaluates expected benefits, costs, risks, strategic alignment, and the value the initiative is expected to deliver. Before a project is formally authorized, decision-makers need sufficient information to determine whether the proposed work supports organizational objectives and warrants investment. The business case serves as a key input to project authorization and often supports the development of the project charter.\n\nCAPM exam logic: PMI expects projects to begin with a valid business need and business justification. The business case helps determine whether the project should be authorized before detailed planning or execution activities begin.","Asking a small team to produce a prototype is incorrect because prototyping is a solution analysis, requirements, or development activity rather than a project initiation activity. A prototype may help validate concepts or requirements, but it does not establish whether the project itself should be authorized. Before resources are committed to creating deliverables, the organization should first confirm that the proposed initiative provides sufficient business value and aligns with strategic objectives. That determination is typically supported by a business case.\n\nCAPM exam logic: PMI expects organizations to justify and authorize projects before beginning solution development work.","Discussing project requirements and evaluating alternative products in the market is incorrect because these activities support solution analysis and decision-making rather than formal project initiation. While market analysis may contribute information for the business case, it does not by itself authorize a project. The primary objective of project initiation is to determine whether a valid business need exists and whether the proposed project should receive organizational approval. A business case provides that justification and supports authorization decisions.\n\nCAPM exam logic: Market analysis can inform project selection decisions, but the business case is the key artifact used to justify and authorize a project."]},{"src":"PK-Q124","d":1,"t":3,"q":"Who is responsible for the business case development document?","o":["Project sponsor","Project stakeholders","Project team","Project manager"],"a":[0],"w":["Project sponsor is correct because the sponsor is typically responsible for developing or ensuring the development of the business case and for securing organizational support for the project. The business case evaluates the expected benefits, costs, risks, strategic alignment, and value justification needed to determine whether the project should be authorized. The sponsor uses the business case to justify the investment and obtain approval to proceed. The document serves as a key input to project initiation and supports the development of the project charter. Because the sponsor is accountable for business value realization and strategic alignment, ownership of the business case generally resides with the sponsor rather than the project manager or project team.\n\nCAPM exam logic: PMI associates the business case with project justification, strategic alignment, and value delivery. When asked who owns or is accountable for the business case, the project sponsor is typically the best answer.","Project stakeholders are incorrect because stakeholders may provide requirements, business needs, subject matter expertise, feedback, or supporting information during business case development, but they do not typically own the document. The business case requires accountability for evaluating strategic benefits, costs, risks, and investment decisions. That accountability normally belongs to the sponsor or sponsoring organization rather than the broader stakeholder community.\n\nCAPM exam logic: PMI often differentiates between contributors and owners. Stakeholders may contribute information to the business case, but the sponsor is generally accountable for its development and approval.","Project team is incorrect because team members are responsible for performing project work and may provide technical expertise, effort estimates, cost information, or feasibility input when requested. However, they are not typically responsible for developing or approving the business case. The business case is a governance and investment justification document created before detailed project execution begins. Its purpose is to support decision-making regarding whether the organization should invest resources in the proposed initiative.\n\nCAPM exam logic: PMI separates project governance activities from project execution activities. The project team helps deliver project outcomes, while the sponsor is responsible for project justification and business case ownership.","Project manager is incorrect because the project manager is usually assigned after project authorization activities have begun and is responsible for planning, executing, monitoring, and controlling project work. While the project manager may contribute estimates, risk information, scheduling input, or feasibility analysis, they are not typically accountable for creating or owning the business case. The business case is developed to justify the project before significant project planning occurs. It focuses on organizational value, expected benefits, and investment decisions, which are responsibilities generally associated with the sponsor and organizational leadership rather than the project manager.\n\nCAPM exam logic: PMI frequently distinguishes project justification from project execution. The sponsor owns the business case, while the project manager manages the authorized project."]},{"src":"P3-Q8","d":4,"t":1,"q":"A business case is being assembled. Which two elements are necessary to complete this process? (Choose two.)","o":["Business goals and objectives","Product roadmap","Requirements traceability matrix","Expected benefits and business value","Project management plan"],"a":[0,3],"w":["Business goals and objectives is correct because a business case must clearly describe the organizational need, opportunity, or problem being addressed and explain how the proposed initiative supports strategic objectives. Clearly defined goals and objectives provide the foundation for evaluating project success, expected benefits, and organizational value. CAPM exam logic: PMI emphasizes strategic alignment and business value as core components of a business case.","Product roadmap is incorrect because a product roadmap is a planning and communication artifact that provides a high-level view of anticipated features, releases, or product direction. While it may support business case discussions in some product-oriented environments, it is not a required element of a business case. CAPM exam logic: distinguish between business justification documents and planning artifacts used later to guide product or project execution.","Requirements traceability matrix is incorrect because the requirements traceability matrix is developed later in planning or execution phases to track requirements through design, development, and testing. It is not a necessary input for creating the initial business case.","Expected benefits and business value is correct because a business case is created to justify an investment by demonstrating the value the proposed initiative will deliver to the organization. Expected benefits help stakeholders evaluate whether the project supports strategic objectives and provides sufficient return to warrant investment. CAPM exam logic: business cases focus on value delivery, benefits realization, and justification for organizational investment decisions.","Project management plan is incorrect because the project management plan is developed after the business case is approved. It defines how the project will be executed, monitored, and controlled, so it is not needed to complete the business case."]},{"src":"P3-Q98","d":1,"t":5,"q":"A project team is evaluating criteria to determine project viability. Which of these activities will provide insight into making a go/no-go decision to start the project?","o":["Cost of quality (COQ)","Cost-benefit analysis","Benchmarking","Lessons learned"],"a":[1],"w":["Cost of quality (COQ) is incorrect. COQ measures the costs associated with ensuring quality, including prevention, appraisal, and failure costs. While useful for planning quality management, it does not determine overall project viability or inform a go/no-go decision.","Cost-benefit analysis is correct. Cost-benefit analysis evaluates the expected financial or strategic benefits relative to costs of a project. It provides a quantifiable assessment of value, helping decision-makers determine whether the project is worthwhile and supports a go/no-go decision. PMI guidance identifies cost-benefit analysis as a key tool for project selection and initiation, ensuring resources are allocated to projects with sufficient expected returns.","Benchmarking  compares processes, performance, or metrics against best practices or similar projects. While benchmarking can provide insights into potential efficiency or performance, it does not directly evaluate the financial or strategic viability of starting a project.","Lessons learned capture knowledge from previous projects and can guide risk management or process improvement. Although valuable for planning, lessons learned alone do not quantify the project’s expected benefits versus costs to support a go/no-go decision."]},{"src":"P5-Q61","d":4,"t":1,"q":"During a kickoff meeting, the project sponsor presents a very ambitious project. Unfortunately, the stakeholders are not very excited as the work associated with the new project seems inefficient. What could be missing from the business case?","o":["Root cause analysis of the problem","Feasibility study of the solution","Approval from the stakeholders","Work breakdown structure (WBS)"],"a":[1],"w":["Root cause analysis helps identify the underlying cause of a problem or opportunity and may contribute to defining the business need. However, stakeholders in this scenario appear concerned that the proposed project requires significant effort without clear evidence that the benefits justify the investment. Understanding the problem alone does not demonstrate whether the proposed solution is practical, achievable, or worth pursuing. CAPM exam logic: A business case must not only explain the problem but also demonstrate that the proposed solution is feasible and valuable.","A feasibility study is the best answer because it evaluates whether the proposed solution can realistically be implemented and whether the expected benefits justify the required investment, effort, risks, and resources. When stakeholders believe a project appears inefficient or overly ambitious, they often need evidence that the solution is technically, operationally, financially, and organizationally feasible. A strong feasibility assessment helps demonstrate expected value, supports informed decision-making, and builds stakeholder confidence in the project’s viability. CAPM exam logic: The business case should justify why a project should be undertaken, and feasibility analysis is a key component used to demonstrate that the proposed solution is practical and worth pursuing.","Stakeholder approval is not typically a component of the business case itself. Instead, approval is an outcome that occurs after decision-makers review the business case and determine that the proposed initiative provides sufficient value. If stakeholders are not enthusiastic about the project, the issue is more likely related to weak justification, unclear benefits, high perceived costs, or concerns about practicality rather than the absence of approval. CAPM exam logic: PMI distinguishes between business case content, which justifies the project, and governance decisions, which occur after the business case is evaluated.","A Work Breakdown Structure (WBS) is a project planning artifact created after the project has been authorized and planning activities begin. Its purpose is to decompose project scope into manageable work packages for estimating, scheduling, and controlling project work. Since the concern occurs during project justification and stakeholder evaluation, the absence of a WBS would not explain why stakeholders doubt the project’s efficiency or value. CAPM exam logic: Business case activities occur before detailed project planning documents such as the WBS are developed."]},{"src":"PK-Q6","d":1,"t":3,"q":"A project manager is assigned to a project, and the sponsor signals to perform first actions. However, the project manager is unsure how to apply organizational resources into project activities before a formal authorization. Which document should be used in this case?","o":["Business case","Budget requirement","Project charter","Project plan"],"a":[2],"w":["The business case provides the justification for undertaking the project by describing the business need, expected benefits, costs, risks, and strategic alignment. It helps decision-makers evaluate whether the project should be approved and is often an input to project initiation. However, the business case does not formally authorize the project manager to apply organizational resources. That authority is granted through the project charter.\n\nCAPM exam logic: PMI distinguishes between documents that justify a project (business case) and documents that formally authorize it (project charter).","A budget requirement identifies funding needs or financial constraints associated with the project. Budget information may be included in business documents, funding approvals, or planning activities and helps support resource allocation decisions. However, funding approval alone does not formally authorize a project or empower the project manager to use organizational resources.\n\nCAPM exam logic: PMI treats the project charter as the official authorization mechanism; budgets support planning and execution but do not replace project authorization.","The project charter is the document that formally authorizes the existence of a project and grants the project manager authority to apply organizational resources to project activities. It establishes the project’s purpose, high-level scope, objectives, key stakeholders, assumptions, constraints, and success criteria. In the scenario, the project manager is unsure whether organizational resources can be used before formal authorization. The charter provides that authorization.\n\nCAPM exam logic: When PMI asks which document officially initiates a project or gives the project manager authority, the answer is the project charter.","The project management plan describes how the project will be executed, monitored, controlled, and closed. It integrates subsidiary plans such as scope, schedule, cost, quality, resource, communications, risk, procurement, and stakeholder management plans. The project management plan is developed after the project has been formally authorized. It provides guidance for managing the project but does not authorize its existence.\n\nCAPM exam logic: PMI distinguishes project authorization documents from project planning documents; authorization occurs through the charter, while the project management plan guides execution."]},{"src":"P3-Q54","d":1,"t":2,"q":"A project manager is creating a project charter to provide a direct link between the project and the organization's strategic objectives. What must be considered when creating this document?","o":["Detailed milestone schedule and project objectives","Key stakeholder list and contingency reserve","High-level requirements and the project team","Project purpose and high-level project description"],"a":[3],"w":["This option is incorrect because project objectives may appear in the charter, but a detailed milestone schedule is developed later as part of project planning. The charter contains high-level information intended to establish direction and authorization, not detailed scheduling information.\n\nPMI differentiates between initiating and planning activities. The charter provides enough information to justify and authorize the project, while detailed schedules are developed after authorization has occurred. CAPM exam logic: if an answer combines a valid charter element with a detailed planning artifact, the option is usually incorrect.","This option is incorrect because contingency reserves are part of project planning and risk management rather than project charter development. While stakeholders may be identified at a high level during initiation, the charter is not primarily intended to serve as a stakeholder register or risk reserve document.\n\nThe project charter focuses on why the project exists, what business need it addresses, and how it supports organizational objectives. CAPM exam logic: distinguish between initiation documents and planning artifacts. Contingency reserves are associated with managing uncertainty during planning, not with formally authorizing the project.","This option is incorrect because although high-level requirements are commonly included in a project charter, the project team is not typically defined during charter development. The charter is created during project initiation and focuses on authorizing the project, establishing its purpose, and linking it to business and strategic objectives.\n\nDetailed team assignments, resource planning, and organizational responsibilities are normally developed later during planning. CAPM exam logic: when evaluating charter content, focus on high-level information that supports project authorization rather than detailed planning information such as team composition.","PMI identifies the project charter as the document that formally authorizes the project and grants the project manager authority to apply organizational resources. The charter typically includes the project purpose, measurable objectives, expected benefits, high-level requirements, assumptions, constraints, risks, success criteria, key stakeholders, and a summary milestone schedule. These elements help demonstrate how the project supports organizational strategy and delivers business value.\n\nCAPM exam logic: when a question emphasizes the connection between a project and organizational strategic objectives, look for answers related to the business need, project purpose, expected benefits, or strategic justification. These charter components provide the direct link between the project and the organization's goals."]},{"src":"P5-Q135","d":1,"t":2,"q":"Which tools and techniques will a project manager use to develop a project charter?","o":["Expert judgment, data gathering, scope statement, schedule baseline, and meetings","Lessons learned database, interpersonal and team skills, cost baseline, and meetings","Project manager experience, expert judgment, scope statement, and meetings","Expert judgment, data gathering, interpersonal and team skills, and meetings"],"a":[3],"w":["Expert judgment, data gathering, and meetings are all legitimate techniques that may support charter development. However, the scope statement and schedule baseline are planning outputs created after the project has been formally authorized. Since the project charter establishes the authority to begin detailed planning, these documents cannot logically be used as charter-development techniques. This option incorrectly includes later planning artifacts and is therefore not correct. CAPM exam logic: The project charter comes before detailed planning outputs such as scope statements and schedule baselines.","Lessons learned repositories can provide valuable historical information and are considered organizational knowledge that may support project initiation. However, they are inputs rather than tools and techniques. Likewise, the cost baseline is a planning output developed much later in the project lifecycle after scope, schedule, and cost planning activities have occurred. This option incorrectly mixes inputs, outputs, and tools and techniques, making it inconsistent with PMI terminology and process flow. CAPM exam logic: Be able to distinguish PMI inputs, tools and techniques, and outputs, especially in project initiation questions.","Project manager experience can contribute to charter development through expert judgment, which PMI recognizes as an important tool and technique. However, the scope statement is not used to create the project charter. The project charter is developed early in the project lifecycle to formally authorize the project and provide high-level objectives, while the scope statement is created later as part of scope planning and definition activities. Because this option includes a planning output that does not yet exist when the charter is created, it is not the best answer. CAPM exam logic: Distinguish between tools and techniques used to create the charter and planning documents that are produced after the charter is approved.","This is the correct answer because PMI identifies expert judgment, data gathering techniques, interpersonal and team skills, and meetings as key methods for developing a project charter. Expert judgment provides knowledge from experienced individuals and subject matter experts. Data gathering techniques such as interviews, brainstorming, and focus groups help collect information about business needs, objectives, assumptions, and stakeholder expectations. Interpersonal and team skills facilitate collaboration, negotiation, and alignment among stakeholders, while meetings help build consensus and confirm project objectives and authorization. Together, these techniques help create a charter that clearly communicates the project’s purpose, expected value, high-level scope, and stakeholder support before detailed planning begins. CAPM exam logic: Questions about project charter development often test recognition of PMI tools and techniques used during project initiation, particularly expert judgment, stakeholder collaboration, and information gathering."]},{"src":"PK-Q39","d":1,"t":2,"q":"In the project charter process, which three of the following are discussed during meetings held with stakeholders? (Choose three.)","o":["Cost","Project objectives","Phase transitions","High-level deliverables","Success criteria"],"a":[1,3,4],"w":["Cost is incorrect because detailed cost estimates, budgets, and funding requirements are generally developed during project planning rather than during project charter development. The charter may contain high-level financial information or a business case reference, but it does not typically include detailed cost planning. The project charter focuses on authorizing the project and establishing a shared understanding of its purpose, objectives, success measures, and major deliverables. Detailed budget development occurs later as planning activities progress.\n\nCAPM exam logic: PMI distinguishes between project authorization activities and detailed planning activities. Cost planning is generally performed after the charter has been approved.","Project objectives are correct because one of the primary purposes of the project charter is to define why the project exists and what outcomes it is expected to achieve. Objectives provide direction for project planning and execution and help align stakeholder expectations. During charter development, stakeholders discuss and confirm the desired business outcomes, strategic alignment, and measurable goals that the project should accomplish.\n\nCAPM exam logic: PMI expects project objectives to be established early because they provide the foundation for scope definition, planning, and project success measurement.","Phase transitions are incorrect because they are typically associated with project life cycle planning, phase reviews, and governance decisions that occur after project authorization. While a charter may reference a project life cycle at a high level, detailed phase transition planning is not usually a primary focus of charter development. The charter concentrates on establishing the project’s purpose, objectives, stakeholders, assumptions, constraints, and high-level expectations rather than detailed execution planning.\n\nCAPM exam logic: PMI generally places detailed life cycle and phase planning activities in project planning rather than project initiation.","High-level deliverables are correct because the project charter identifies the major outputs, products, services, or results that the project is expected to produce. These deliverables help stakeholders understand the scope and intended outcomes of the project. Defining high-level deliverables during charter development establishes a common understanding of what the project will create and provides a basis for later scope definition and work breakdown activities.\n\nCAPM exam logic: PMI expects the charter to contain enough information to authorize the project and establish stakeholder alignment regarding the project’s major expected outcomes.","Success criteria are correct because stakeholders must establish how project success will be evaluated. Success criteria provide measurable indicators that help determine whether the project has achieved its intended objectives and business value. Defining success criteria during charter development promotes alignment among stakeholders and reduces ambiguity regarding expected outcomes.\n\nCAPM exam logic: PMI frequently emphasizes defining success measures early so stakeholders share a common understanding of what constitutes successful project completion."]}]},{"title":"Requirements, Prioritization & Acceptance Criteria","desc":"Peran business analyst, Collect Requirements, jenis requirement, prioritas, acceptance criteria, RTM dan product roadmap.","qs":[{"src":"PK-Q132","d":4,"t":1,"q":"A project manager is seeking assistance from a business analyst in defining stakeholder and product needs. Which activity would the business analyst most likely perform?","o":["Manage the project schedule.","Verify product functionality.","Allocate project resources.","Elicit product requirements."],"a":[3],"w":["Managing the project schedule is primarily the responsibility of the project manager. Schedule management includes defining activities, sequencing work, estimating durations, developing the schedule, and monitoring schedule performance throughout the project lifecycle. A business analyst may provide information about requirement dependencies, business priorities, or impacts that affect scheduling decisions, but the business analyst does not own or manage the project schedule.\n\nCAPM exam logic: PMI distinguishes project management responsibilities from business analysis responsibilities. Schedule management belongs to the project manager rather than the business analyst.","Verifying product functionality is associated with testing, quality control, and product validation activities. While business analysts may help define acceptance criteria, review results, and confirm that requirements have been met, they are not typically responsible for performing functional verification. The business analyst’s primary role is ensuring that stakeholder needs and requirements are correctly understood and documented before and throughout solution development.\n\nCAPM exam logic: PMI expects candidates to distinguish between defining requirements and testing whether a completed solution functions correctly. The former is a business analysis responsibility, while the latter is generally performed by development, testing, or quality teams.","Resource allocation involves acquiring, assigning, and managing human and physical resources needed to perform project work. These responsibilities typically belong to the project manager and organizational resource managers. A business analyst may help identify required skills, stakeholder expertise, or subject matter experts needed to support requirements activities, but does not generally assign project resources.\n\nCAPM exam logic: Questions involving staffing, resource assignment, and resource optimization usually relate to Project Resource Management rather than business analysis.","Eliciting product requirements is a core responsibility of the business analyst. Business analysts work with stakeholders to identify, gather, analyze, and document business and product requirements that support organizational objectives and expected outcomes. Common elicitation techniques include interviews, workshops, observation, surveys, document analysis, and prototyping. Accurate requirements provide the foundation for solution design, prioritization, validation, and value delivery throughout the project lifecycle.\n\nCAPM exam logic: When a question focuses on understanding stakeholder needs, gathering requirements, or defining solution requirements, PMI typically associates those activities with the business analyst."]},{"src":"P3-Q9","d":4,"t":3,"q":"What tool or technique is used in the Collect Requirements process?","o":["Control charts","Inspection","Decomposition","Product analysis"],"a":[3],"w":["Control charts is incorrect because control charts are a quality management tool used to determine whether a process is stable and within acceptable limits. They are primarily associated with quality control and process performance monitoring, not with eliciting or analyzing stakeholder requirements. CAPM exam logic: distinguish requirements collection techniques from quality control tools used later to monitor performance.","Inspection is incorrect because inspection is used to examine, review, or verify work products and deliverables against defined requirements and acceptance criteria. It is commonly associated with quality management and scope validation activities rather than eliciting stakeholder requirements. CAPM exam logic: inspection verifies whether requirements have been met, while Collect Requirements focuses on discovering and defining those requirements.","Decomposition is incorrect because decomposition is primarily used to break down project scope, deliverables, or work packages into smaller and more manageable components. It is commonly associated with creating the WBS and defining activities rather than gathering stakeholder requirements. CAPM exam logic: decomposition organizes and structures work after scope is understood, whereas Collect Requirements focuses on eliciting and documenting stakeholder needs and expectations.","Product analysis is correct because it is a recognized tool and technique used in the Collect Requirements process. Product analysis examines the characteristics, functions, features, and performance requirements of a product or service to help stakeholders identify and define detailed requirements. By analyzing what the product must do and how it should perform, the project team can derive more complete and accurate requirements. CAPM exam logic: when a question focuses on understanding product features, functions, and characteristics to identify requirements, product analysis is a strong PMI answer."]},{"src":"P3-Q142","d":4,"t":3,"q":"A team was hired to develop a next generation drone. The team created a prototype and sent it to the customer for testing. The feedback collected was used to refine the requirements. What technique is the team using?","o":["Requirements documentation","Prototyping","Progressive elaboration","Early requirements gathering"],"a":[1],"w":["Requirements documentation is an output of the Collect Requirements process . While requirements may be updated, the technique described in the scenario is iterative refinement through prototyping and feedback, not simply documenting requirements.","Prototyping is correct because it involves creating a model, mockup, or working representation of a product so stakeholders can review it and provide feedback. The feedback is then used to clarify, validate, and refine requirements before full-scale development proceeds. Prototyping helps reduce misunderstandings, improve requirement quality, and ensure the solution aligns with stakeholder expectations. CAPM exam logic: when a scenario describes building something for stakeholder review and using the feedback to refine requirements, prototyping is typically the best answer.","Progressive elaboration is incorrect because it refers to the ongoing process of developing plans and project information in greater detail as more information becomes available. While the scenario results in progressively elaborated requirements, the specific technique being used to obtain the information is prototyping. CAPM exam logic: distinguish between a management concept (progressive elaboration) and the actual technique used to gather feedback (prototyping).","Early requirements gathering refers to eliciting and documenting stakeholder needs at the beginning of the project . In the scenario, requirements are being refined after building and testing a prototype. This indicates iterative refinement rather than initial elicitation."]},{"src":"P3-Q29","d":4,"t":3,"q":"What are the requirements that describe the behaviors of a product called?","o":["Transition requirements","Functional requirements","Nonfunctional requirements","Solution requirements"],"a":[1],"w":["Transition requirements are incorrect because they describe the temporary capabilities and conditions needed to move a solution from its current state into operational use. Examples include data migration, user training, deployment activities, and conversion requirements.\n\nThese requirements support implementation and adoption of the solution but do not define how the product behaves once it is operational. CAPM exam logic: transition requirements help implement the solution, while functional requirements define the solution's behavior and capabilities.","Functional requirements are correct because they define what a product, system, or solution must do. They describe the behaviors, capabilities, functions, and business rules that the solution must support. Examples include processing transactions, generating reports, validating user input, or performing calculations.\n\nPMI business analysis guidance identifies functional requirements as a subset of solution requirements that specify product behavior and functionality. These requirements provide the foundation for solution design, development, testing, and acceptance. CAPM exam logic: when a question asks what a product does or how it behaves, think of functional requirements.","Nonfunctional requirements are incorrect because they define how well a system performs rather than what it does. These requirements describe quality attributes and operational characteristics such as performance, reliability, availability, security, maintainability, and usability.\n\nWhile nonfunctional requirements are essential for solution success, they do not define the specific functions or behaviors of the product. CAPM exam logic: functional requirements describe product behavior, whereas nonfunctional requirements describe performance and quality characteristics.","Solution requirements are incorrect because this is a broader category that includes both functional requirements and nonfunctional requirements. Solution requirements collectively describe the characteristics needed for a solution to meet business and stakeholder needs.\n\nBecause the question specifically asks for the requirements that describe product behaviors, the more precise answer is functional requirements. CAPM exam logic: when both a broad category and a more specific subtype appear as answer choices, PMI typically expects the most precise answer that directly addresses the question."]},{"src":"P3-Q11","d":4,"t":3,"q":"While gathering nonfunctional requirements for developing a portal, which three aspects should a business analyst check to ensure that the solution developed will be fit for use by the customer? (Choose three.)","o":["Uptime","Data integrity","Order submission","User registration","Reliability"],"a":[0,1,4],"w":["Uptime is correct because it measures system availability, which is a key nonfunctional requirement. Customers expect the portal to be accessible when needed, and availability directly affects user satisfaction and business operations. Defining uptime requirements helps ensure the solution meets agreed service levels and operational expectations. CAPM exam logic: availability requirements describe how reliably a system can be accessed and are common examples of nonfunctional requirements.","Data integrity is correct because it ensures that information remains accurate, complete, consistent, and protected from unauthorized modification throughout its lifecycle. Maintaining data integrity is essential for customer trust, regulatory compliance, and effective business operations. It describes a quality characteristic of the solution rather than a specific system function. CAPM exam logic: requirements that define data quality, accuracy, consistency, and protection are nonfunctional requirements.","Order submission is incorrect because it describes a specific capability that the portal must provide to users. Functional requirements define what the system must do, such as registering users, processing orders, generating reports, or submitting transactions. In contrast, nonfunctional requirements describe how well the system performs, including attributes such as reliability, availability, security, and data integrity. CAPM exam logic: if a requirement describes a specific feature, action, or business process the system must perform, it is typically a functional requirement rather than a nonfunctional requirement.","User registration is incorrect because it describes a specific function or capability that the portal must perform for its users. Functional requirements define the features, actions, and behaviors of a system, such as creating accounts, submitting orders, processing payments, or generating reports. Nonfunctional requirements, by contrast, define quality attributes such as reliability, availability, security, performance, and data integrity. CAPM exam logic: if a requirement describes what the system must do, it is a functional requirement; if it describes how well the system must operate, it is a nonfunctional requirement.","Reliability is correct because it measures the system’s ability to perform consistently and correctly under expected operating conditions over time. A reliable portal minimizes failures, service interruptions, and unexpected behavior, helping ensure a dependable customer experience. Reliability describes the quality of system performance rather than a specific feature or function. CAPM exam logic: reliability is one of the most common nonfunctional requirements because it defines how dependably the solution performs."]},{"src":"P3-Q14","d":4,"t":5,"q":"A business analyst is working on a project that follows an adaptive life cycle. Due to budgetary constraints, the sponsor asks the team to focus on critical requirements. What should the business analyst do?","o":["Trace requirements.","Document requirements.","Validate requirements.","Prioritize requirements."],"a":[3],"w":["Trace requirements is incorrect because requirements traceability helps verify that requirements are linked to business objectives, design components, test cases, and deliverables throughout the project life cycle. Traceability supports impact analysis, verification, and change management.\n\nAlthough tracing requirements improves visibility and control, it does not determine which requirements should be implemented first when budget constraints exist. CAPM exam logic: When a scenario focuses on selecting the most important work under constraints, prioritization is the PMI-preferred action rather than traceability.","Document requirements is incorrect because documenting requirements ensures that stakeholder needs, acceptance criteria, assumptions, constraints, and business objectives are clearly captured and communicated. Proper documentation supports analysis, development, testing, validation, and future change management activities throughout the project life cycle.\n\nHowever, the scenario focuses on deciding which requirements should receive priority when budget constraints limit delivery capacity. Documentation records requirements but does not determine their relative importance or implementation order. CAPM exam logic: When PMI emphasizes limited resources, budget constraints, or maximizing value, prioritization is the preferred action rather than additional documentation.","Validate requirements is incorrect because requirements validation confirms that documented requirements accurately reflect stakeholder needs, support business objectives, and are complete, feasible, and understandable. Validation helps ensure the project is building the right solution before significant resources are committed.\n\nWhile validation improves requirement quality and stakeholder alignment, it does not address which requirements should be implemented first when budget limitations exist. CAPM exam logic: PMI distinguishes between ensuring requirements are correct (validation) and determining which requirements deliver the greatest value under constraints (prioritization). In adaptive environments, prioritization is the appropriate response when resources are limited.","Prioritize requirements is correct because adaptive approaches emphasize delivering the highest-value requirements first when resources, budget, or time are constrained. The business analyst should collaborate with stakeholders and the product owner (if applicable) to evaluate requirements based on business value, risk reduction, dependencies, and alignment with business objectives.\n\nPrioritization ensures that the most valuable functionality is delivered within available constraints while lower-priority requirements can be deferred to future iterations or releases. CAPM exam logic: PMI emphasizes value-driven delivery, backlog prioritization, and continuous refinement in adaptive environments. When budget constraints limit what can be delivered, prioritizing requirements is the preferred response to maximize business value."]},{"src":"P3-Q127","d":3,"t":4,"q":"An adaptive project team is grooming the backlog for the next iteration. What does the team need to document in the user stories to determine the work needed to complete each story?","o":["Detailed acceptance criteria","Related epics of each story","Product owner's priorities","Team velocity in past iterations"],"a":[0],"w":["Detailed acceptance criteria is correct because acceptance criteria define the specific conditions that must be satisfied for a user story to be considered complete and acceptable. They clarify scope, expected behavior, business rules, constraints, and quality expectations, enabling the team to understand exactly what must be delivered.\n\nDuring backlog refinement or grooming, acceptance criteria help the team decompose work, identify tasks, estimate effort, and establish a shared understanding with stakeholders and the product owner. CAPM exam logic: In adaptive and Agile environments, acceptance criteria are a key component of user stories because they define completion requirements and support value-driven delivery. When PMI asks how a team determines the work necessary to complete a story, acceptance criteria are the most direct and complete answer.","Related epics of each story is incorrect because epics are large bodies of work that group related user stories and provide context about broader features, capabilities, or business objectives. Linking a story to an epic helps the team understand how the story contributes to a larger product goal.\n\nHowever, epics do not define the specific conditions that must be met for a story to be completed. A team cannot determine the detailed work, testing needs, or completion requirements from the epic relationship alone. CAPM exam logic: PMI expects candidates to distinguish between backlog hierarchy elements and story completion criteria. Epics provide context and organization, while acceptance criteria define what must be delivered for a story to be considered done.","Product owner's priorities is incorrect because prioritization determines the relative importance and implementation order of backlog items based on business value, risk, dependencies, and stakeholder needs. Priorities help the team decide what should be worked on first but do not explain how a story will be completed.\n\nThe question focuses on determining the work needed to complete a specific user story. That requires understanding the story's detailed expectations and completion conditions, which are documented in the acceptance criteria. CAPM exam logic: PMI distinguishes between deciding which work should be done first (prioritization) and defining what constitutes successful completion of that work (acceptance criteria). When completion requirements are being evaluated, acceptance criteria are the preferred answer.","Team velocity in past iterations is incorrect because velocity measures the amount of work a team has historically completed during an iteration and is primarily used for forecasting and release planning. It helps the team estimate how many user stories can likely be completed in future iterations based on demonstrated capacity.\n\nThe question asks what must be documented in the user story to determine the work needed to complete that specific story. Velocity provides capacity information at the iteration level but does not define the conditions, requirements, or expected outcomes for an individual story. CAPM exam logic: PMI distinguishes between planning metrics such as velocity and story-level details such as acceptance criteria. When determining what work is required to complete a user story, focus on acceptance criteria rather than team performance metrics."]},{"src":"P3-Q22","d":4,"t":6,"q":"What can a requirements traceability matrix enable regardless of the project methodology being used?","o":["Evaluation of solution and system performance","Identification of missing and superfluous requirements","Investigation of the viability of a new product","Creation of a solid business case"],"a":[1],"w":["Investigation of the viability of a new product is incorrect because product viability is typically evaluated through business analysis activities such as feasibility studies, market analysis, cost-benefit analysis, and risk assessments. The Requirements Traceability Matrix (RTM) focuses on tracing requirements from their origin through implementation, testing, and acceptance rather than determining whether a product should be developed. CAPM exam logic: the RTM manages requirements after they are identified; it is not a tool for evaluating business viability.","Identification of missing and superfluous requirements is correct because the Requirements Traceability Matrix links each requirement to its source, related deliverables, design elements, test cases, and acceptance criteria. By maintaining these relationships, the project team can identify requirements that are missing, duplicated, unnecessary, or not connected to project work. This helps improve completeness, reduce scope creep, and ensure that all approved requirements are addressed regardless of whether the project uses a predictive, agile, or hybrid approach. CAPM exam logic: one of the key benefits of the RTM is ensuring complete traceability and identifying gaps or unnecessary requirements throughout the project lifecycle.","Investigation of the viability of a new product is incorrect because product viability is typically evaluated through business analysis activities such as feasibility studies, market analysis, cost-benefit analysis, and risk assessments. The Requirements Traceability Matrix (RTM) focuses on tracing requirements from their origin through implementation, testing, and acceptance rather than determining whether a product should be developed. CAPM exam logic: the RTM manages requirements after they are identified; it is not a tool for evaluating business viability.","Creation of a solid business case is incorrect because a business case is developed to justify the project’s value, feasibility, and expected benefits before significant project work begins. Although requirements may contribute information used in business analysis and decision-making, the Requirements Traceability Matrix (RTM) is not intended to create or strengthen the business case. Its primary purpose is to track requirements throughout the project lifecycle and ensure they are addressed by project work and deliverables. CAPM exam logic: distinguish between documents that justify a project and tools that manage and track requirements."]},{"src":"PK-Q30","d":4,"t":6,"q":"What is the difference between verified and accepted deliverables?","o":["Accepted deliverables have been formally signed off and approved by the authorized stakeholder; verified deliverables have been completed and checked for correctness.","Accepted deliverables have been completed and checked for correctness; verified deliverables have been formally approved by the customer or authorized stakeholder.","Accepted deliverables have been inspected by the quality team; verified deliverables are outputs from the Validate Scope process.","Accepted deliverables have been formally accepted by the project manager; verified deliverables are the outputs from the Control Quality process"],"a":[0],"w":["Accepted deliverables have been formally signed off and approved by the authorized stakeholder; verified deliverables have been completed and checked for correctness is correct because verified deliverables are completed deliverables that have been inspected and confirmed to meet documented quality requirements through the Control Quality process. They represent work that has passed internal quality checks and is ready for stakeholder review. Accepted deliverables are verified deliverables that have been formally reviewed and approved by the customer, sponsor, or authorized stakeholder during the Validate Scope process. Formal acceptance confirms that the deliverable satisfies requirements, business needs, and acceptance criteria.\n\nCAPM exam logic: PMI frequently tests the distinction between Control Quality and Validate Scope. Control Quality produces verified deliverables, while Validate Scope produces accepted deliverables through formal stakeholder acceptance.","Accepted deliverables have been completed and checked for correctness; verified deliverables have been formally approved by the customer or authorized stakeholder is incorrect because it reverses the PMI definitions. Verified deliverables are the deliverables that have undergone internal inspection and quality review to confirm that they meet documented requirements and quality standards. Accepted deliverables are verified deliverables that have subsequently been reviewed and formally approved by the customer, sponsor, or authorized stakeholder during scope validation activities. Formal acceptance indicates that stakeholder expectations and acceptance criteria have been satisfied.\n\nCAPM exam logic: PMI frequently tests the sequence of deliverable approval. Deliverables are first verified through Control Quality and then become accepted deliverables after formal stakeholder approval in Validate Scope.","Accepted deliverables have been inspected by the quality team; verified deliverables are outputs from the Validate Scope process is incorrect because it incorrectly assigns the outputs of the Control Quality and Validate Scope processes. Verified deliverables are produced during Control Quality after internal inspection confirms compliance with quality requirements. Accepted deliverables are the outputs of Validate Scope, where stakeholders formally review and approve verified deliverables. Inspection by the quality team alone does not create accepted deliverables because stakeholder acceptance is still required.\n\nCAPM exam logic: PMI expects candidates to distinguish between internal quality verification and formal stakeholder acceptance. Control Quality produces verified deliverables, while Validate Scope produces accepted deliverables.","Accepted deliverables have been formally accepted by the project manager; verified deliverables are the outputs from the Control Quality process is incorrect because although verified deliverables are indeed outputs of the Control Quality process, the project manager is not typically the authority responsible for formal acceptance of deliverables. Formal acceptance is performed by the customer, sponsor, product owner, or another authorized stakeholder with acceptance authority. The project manager facilitates the process but does not generally provide the official approval that converts verified deliverables into accepted deliverables.\n\nCAPM exam logic: PMI often tests stakeholder roles and governance responsibilities. The project manager manages delivery and coordination, while authorized stakeholders provide formal acceptance of completed deliverables.on misstates the authority responsible for acceptance."]},{"src":"P3-Q48","d":4,"t":4,"q":"What is the main purpose of a product roadmap?","o":["Limit the product scope and reduce the likelihood of changes in the future.","Clarify the business value of each new feature and its relevance.","Educate customers on what changes to expect so they are prepared before they are published.","Provide a view of new product features and the expected sequence of delivery by release."],"a":[3],"w":["Limiting product scope and reducing the likelihood of future changes is incorrect because a product roadmap is not intended to lock down scope or prevent change. Particularly in agile and adaptive environments, roadmaps are expected to evolve as stakeholder feedback, market conditions, risks, and business priorities change. The roadmap provides direction and visibility while maintaining enough flexibility to accommodate learning and changing needs. CAPM exam logic: roadmaps communicate future direction but are not fixed commitments that eliminate change.","Clarifying the business value of each new feature and its relevance is incorrect because detailed value analysis is typically performed through business cases, product strategies, prioritization activities, or value assessments. Although a roadmap may reflect priorities that are influenced by business value, its purpose is not to provide a detailed justification for every feature. Instead, it communicates the planned progression of product development and delivery. CAPM exam logic: product roadmaps show what is planned and when, while business cases and prioritization activities explain why specific features are valuable.","Educating customers about upcoming changes is incorrect because customer communication is only one possible use of a product roadmap, not its primary purpose. A product roadmap is primarily a strategic planning and communication tool that helps stakeholders understand the intended direction of the product, upcoming releases, and delivery priorities. While roadmap information may be shared with customers, its main function is to align teams and stakeholders around the product vision and planned evolution. CAPM exam logic: distinguish between a roadmap’s strategic planning purpose and its secondary communication benefits.","Providing a view of new product features and the expected sequence of delivery by release is correct because a product roadmap communicates the planned evolution of a product over time. It presents high-level information about upcoming features, releases, priorities, and target timeframes, allowing stakeholders to understand what is expected to be delivered and when. Product roadmaps support decision-making, stakeholder alignment, prioritization, and expectation management while maintaining flexibility to adapt as business needs change. CAPM exam logic: a product roadmap provides a high-level view of future product direction, planned features, and release sequencing."]}]}];

export const CAPM_CHAPTERS = CAPM_RAW_DATA as unknown as CapmChapter[];

CAPM_CHAPTERS.forEach((c, ci) =>
  c.qs.forEach((q, qi) => {
    q.id = `C${ci + 1}Q${qi + 1}`;
    q.ci = ci;
    q.qi = qi;
  }),
);

export const CAPM_ALL: CapmQuestion[] = CAPM_CHAPTERS.flatMap((c) => c.qs);
